def get_tifek_pub():
    current_path = Path(__file__).parent.parent.parent
    tifek_path = Path(current_path, "tifek","tifekpub.pem")
    return tifek_path


def get_output_path(device:str="sptcert"):
    # Use os.path.expanduser to get home directory cross-platform
    home = os.path.expanduser("~")
    output_path = Path(home, "ti", device + "/certificates")
    return output_path
